use std :: collections :: HashMap ; use std :: time :: Instant ; use std :: fs ; fn benchmark_complexity_calculation () -> Vec < BenchmarkResult > { let mut results = Vec :: new () ; println ! ("  📊 Benchmarking single repository complexity calculation...") ; let start = Instant :: now () ; for _ in 0 .. 1000 { let mut complexity = 0.0 ; let stars = 1000 ; let forks = 500 ; let contributors = 100 ; let size_mb = 100 ; let last_commit_days = 10 ; complexity += (stars as f64 + 1.0) . log10 () * 0.25 ; complexity += (forks as f64 + 1.0) . log10 () * 0.15 ; complexity += (contributors as f64 + 1.0) . log10 () * 0.20 ; complexity += (size_mb as f64 + 1.0) . log10 () * 0.10 ; if last_commit_days > 0 { complexity += (365.0 / last_commit_days as f64) . log10 () * 0.10 ; } } let duration = start . elapsed () ; let operations_per_second = 1000.0 / (duration . as_millis () as f64 / 1000.0) ; results . push (BenchmarkResult :: new ("Single Repository Complexity" . to_string () , duration . as_millis () as u64 , operations_per_second , 0.0 , true , None ,)) ; println ! ("  📊 Benchmarking multiple repository complexity calculation...") ; let start = Instant :: now () ; for repo_index in 0 .. 100 { let mut complexity = 0.0 ; let stars = repo_index * 100 ; let forks = repo_index * 50 ; let contributors = repo_index * 10 ; let size_mb = repo_index * 10 ; let last_commit_days = repo_index % 365 + 1 ; complexity += (stars as f64 + 1.0) . log10 () * 0.25 ; complexity += (forks as f64 + 1.0) . log10 () * 0.15 ; complexity += (contributors as f64 + 1.0) . log10 () * 0.20 ; complexity += (size_mb as f64 + 1.0) . log10 () * 0.10 ; if last_commit_days > 0 { complexity += (365.0 / last_commit_days as f64) . log10 () * 0.10 ; } } let duration = start . elapsed () ; let operations_per_second = 100.0 / (duration . as_millis () as f64 / 1000.0) ; results . push (BenchmarkResult :: new ("Multiple Repository Complexity" . to_string () , duration . as_millis () as u64 , operations_per_second , 0.0 , true , None ,)) ; println ! ("  📊 Benchmarking large scale complexity calculation...") ; let start = Instant :: now () ; for _ in 0 .. 10 { for repo_index in 0 .. 1000 { let mut complexity = 0.0 ; let stars = repo_index * 100 ; let forks = repo_index * 50 ; let contributors = repo_index * 10 ; let size_mb = repo_index * 10 ; let last_commit_days = repo_index % 365 + 1 ; complexity += (stars as f64 + 1.0) . log10 () * 0.25 ; complexity += (forks as f64 + 1.0) . log10 () * 0.15 ; complexity += (contributors as f64 + 1.0) . log10 () * 0.20 ; complexity += (size_mb as f64 + 1.0) . log10 () * 0.10 ; if last_commit_days > 0 { complexity += (365.0 / last_commit_days as f64) . log10 () * 0.10 ; } } } let duration = start . elapsed () ; let operations_per_second = (10.0 * 1000.0) / (duration . as_millis () as f64 / 1000.0) ; results . push (BenchmarkResult :: new ("Large Scale Complexity" . to_string () , duration . as_millis () as u64 , operations_per_second , 0.0 , true , None ,)) ; results }